/**
 * Probe: how much of a growing conversation prefix the product reads from cache
 * under three ways of driving the Agent SDK from a stateless-per-step caller.
 *
 * Usage: node probe.mjs <A|B|C> [steps]
 */

import { mkdirSync, rmSync, existsSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { randomUUID } from 'node:crypto'
import { query } from '@anthropic-ai/claude-agent-sdk'
import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { CallToolRequestSchema, ListToolsRequestSchema } from '@modelcontextprotocol/sdk/types.js'

const DESIGN = (process.argv[2] ?? 'A').toUpperCase()
const STEPS = Number(process.argv[3] ?? 10)
const EXECUTABLE = process.env.PROBE_CLAUDE ?? '/opt/node22/bin/claude'
const CONFIG_DIR = '/tmp/route-probe/config'

const SYSTEM = [
  'You are the implementer agent of an automated software harness. The harness owns the loop: you answer',
  'exactly one turn at a time and the harness executes every tool call you request, then returns its result',
  'in the next turn. Never explain your plan at length. Prefer one tool call per turn. The workspace is a',
  'TypeScript monorepo whose packages live under packages/<group>/<name>/src. Treat every file path as',
  'relative to the repository root. Do not ask questions; act.',
].join(' ')
console.assert(SYSTEM.length > 500, `system prompt ${SYSTEM.length} chars`)

const TASK = `Audit the token accounting of the LLM route packages and report which files compute usage.
The repository is a pnpm workspace with roughly forty packages grouped by capability. The LLM capability
lives under packages/llm and contains the seam package (llm), two keyed providers (llm-deepseek, llm-pi-ai),
a retry wrapper (llm-retry), and a token meter (token-meter). Each provider maps its wire usage record onto
the seam's disjoint TokenUsage counts: input, output, cache read, cache write. The seam requires the four
counts to be disjoint, so a provider whose wire reports cached input inside the input total must subtract it.
Your job is to walk the provider sources one file at a time using the probe_read tool, and for each file
state in one sentence whether it computes usage and whether the counts it produces are disjoint. Do not
guess at file contents: read every file you name. Work through the files in the order the harness gives
them to you, one per turn, and keep each reply to a single sentence plus the next tool call. When you have
read every file the harness offers, say DONE and stop calling tools. Begin with the first file below.`
console.assert(TASK.length > 1000, `task ${TASK.length} chars`)

const FILES = [
  'packages/llm/llm/src/types.ts',
  'packages/llm/llm/src/assembler.ts',
  'packages/llm/llm-deepseek/src/usage.ts',
  'packages/llm/llm-deepseek/src/adapter.ts',
  'packages/llm/llm-pi-ai/src/usage.ts',
  'packages/llm/llm-pi-ai/src/adapter.ts',
  'packages/llm/llm-retry/src/policy.ts',
  'packages/llm/token-meter/src/meter.ts',
  'packages/llm/token-meter/src/window.ts',
  'packages/llm/llm/src/retry-policy.ts',
]

/** A 1-3 KB canned tool result, deterministic per step. */
function cannedResult(step) {
  const path = FILES[step % FILES.length]
  const lines = [`// ${path}`, `// generated for probe step ${step}`]
  const body = 40 + (step % 3) * 20
  for (let i = 0; i < body; i += 1) {
    lines.push(`export const value${i} = { index: ${i}, label: 'usage-field-${i}', disjoint: ${i % 2 === 0} }`)
  }
  return lines.join('\n')
}

const TOOL = {
  name: 'probe_read',
  description: 'Read one file of the workspace and return its contents.',
  inputSchema: {
    type: 'object',
    properties: {
      path: { type: 'string', description: 'Repository-relative path of the file to read.' },
    },
    required: ['path'],
    additionalProperties: false,
  },
}

const QUEUED_CALL_TEXT = 'Queued for the harness.'

function makeOffer() {
  const instance = new McpServer({ name: 'dsh', version: '1' }, { capabilities: { tools: {} } })
  instance.server.setRequestHandler(ListToolsRequestSchema, () => ({ tools: [TOOL] }))
  instance.server.setRequestHandler(CallToolRequestSchema, () => ({
    content: [{ type: 'text', text: QUEUED_CALL_TEXT }],
  }))
  return {
    server: { type: 'sdk', name: 'dsh', instance },
    allowedTools: [`mcp__dsh__${TOOL.name}`],
    close: () => instance.close(),
  }
}

/** Render the whole conversation the way packages/llm/llm-claude-code/src/render.ts does. */
function renderWhole(messages) {
  const out = [
    'Answer the last turn of the conversation below. Elements tagged `<dsh-…>` are the harness\'s'
    + ' framing; everything between them is the conversation.',
    '<dsh-conversation>',
  ]
  for (const m of messages) {
    if (m.role === 'user') {
      if (m.toolResultFor === undefined) {
        out.push('<dsh-user>', m.text, '</dsh-user>')
      } else {
        out.push(`<dsh-tool-result id="${m.toolResultFor}" status="ok">`, m.text, '</dsh-tool-result>')
      }
    } else {
      out.push('<dsh-assistant>')
      if (m.text.length > 0) out.push(m.text)
      for (const call of m.calls) {
        out.push(`<dsh-tool-call id="${call.id}" name="${call.name}">`, call.args, '</dsh-tool-call>')
      }
      out.push('</dsh-assistant>')
    }
  }
  out.push('</dsh-conversation>')
  return `${out.join('\n')}\n`
}

/** Render only the newest user turn, for a session that already holds the prefix. */
function renderDelta(message) {
  if (message.toolResultFor === undefined) {
    return `<dsh-user>\n${message.text}\n</dsh-user>\n`
  }
  return `<dsh-tool-result id="${message.toolResultFor}" status="ok">\n${message.text}\n</dsh-tool-result>\n`
}

function baseOptions(offer, extra) {
  return {
    cwd: '/tmp/route-probe',
    pathToClaudeCodeExecutable: EXECUTABLE,
    env: { ...process.env, ...extra.env },
    systemPrompt: SYSTEM,
    includePartialMessages: false,
    maxTurns: 1,
    permissionMode: 'dontAsk',
    tools: [],
    allowedTools: offer.allowedTools,
    disallowedTools: ['AskUserQuestion'],
    mcpServers: { dsh: offer.server },
    strictMcpConfig: true,
    settingSources: [],
    ...extra.options,
  }
}

/** Drive one query to its result, collecting assistant messages and the result. */
async function runQuery(prompt, options) {
  const q = query({ prompt, options })
  const assistants = []
  let result
  let sessionId
  for await (const message of q) {
    if (message.type === 'assistant') assistants.push(message)
    if (message.type === 'result') result = message
    if (message.type === 'system' && message.subtype === 'init') sessionId = message.session_id
  }
  try {
    q.close?.()
  } catch {
    // The generator is already returned; closing a finished query is a no-op that may throw.
  }
  return { assistants, result, sessionId: result?.session_id ?? sessionId }
}

function answerOf(assistants) {
  const texts = []
  const calls = []
  for (const message of assistants) {
    for (const block of message.message.content) {
      if (block.type === 'text') texts.push(block.text)
      if (block.type === 'tool_use') {
        calls.push({ id: block.id, name: block.name.replace('mcp__dsh__', ''), args: JSON.stringify(block.input) })
      }
    }
  }
  return { text: texts.join(''), calls }
}

function usageOf(result) {
  const u = result?.usage ?? {}
  return {
    input: u.input_tokens ?? 0,
    output: u.output_tokens ?? 0,
    cacheWrite: u.cache_creation_input_tokens ?? 0,
    cacheRead: u.cache_read_input_tokens ?? 0,
  }
}

function diskBytes(dir) {
  if (!existsSync(dir)) return 0
  const out = execSync(`du -sb ${dir}`, { encoding: 'utf8' })
  return Number(out.split('\t')[0])
}

async function main() {
  rmSync(CONFIG_DIR, { recursive: true, force: true })
  mkdirSync(CONFIG_DIR, { recursive: true })
  const steps = []
  let processStarts = 0
  const messages = [{ role: 'user', text: `${TASK}\n\nFirst file: ${FILES[0]}` }]
  const started = Date.now()

  if (DESIGN === 'C') {
    await runStreaming(steps, messages)
    processStarts = 1
  } else {
    let productSession
    for (let step = 0; step < STEPS; step += 1) {
      const offer = makeOffer()
      const resuming = DESIGN === 'B' && productSession !== undefined
      const prompt = resuming
        ? renderDelta(messages[messages.length - 1])
        : renderWhole(messages)
      const extra = DESIGN === 'B'
        ? {
          env: { CLAUDE_CONFIG_DIR: CONFIG_DIR },
          options: {
            persistSession: true,
            ...resuming ? { resume: productSession } : { sessionId: randomUUID() },
          },
        }
        : { env: {}, options: { persistSession: false } }
      const t0 = Date.now()
      const { assistants, result, sessionId } = await runQuery(prompt, baseOptions(offer, extra))
      processStarts += 1
      await offer.close()
      const answer = answerOf(assistants)
      productSession = sessionId
      steps.push({
        step: step + 1,
        ms: Date.now() - t0,
        subtype: result?.subtype,
        calls: answer.calls.length,
        ...usageOf(result),
      })
      if (answer.calls.length === 0) {
        messages.push({ role: 'assistant', text: answer.text, calls: [] })
        break
      }
      messages.push({ role: 'assistant', text: answer.text, calls: answer.calls })
      messages.push({
        role: 'user',
        toolResultFor: answer.calls[0].id,
        text: cannedResult(step),
      })
    }
  }

  report(steps, Date.now() - started, processStarts)
}

/** Design C: one query, the conversation pushed as an async iterable of user messages. */
async function runStreaming(steps, messages) {
  const offer = makeOffer()
  let push
  let closed = false
  const pending = []
  const waiters = []
  const enqueue = (value) => {
    const waiter = waiters.shift()
    if (waiter !== undefined) waiter(value)
    else pending.push(value)
  }
  push = (text) => enqueue({
    type: 'user',
    message: { role: 'user', content: text },
    parent_tool_use_id: null,
    session_id: '',
  })
  const iterable = {
    async *[Symbol.asyncIterator]() {
      while (!closed) {
        const value = pending.length > 0
          ? pending.shift()
          : await new Promise((resolve) => { waiters.push(resolve) })
        if (value === undefined) return
        yield value
      }
    },
  }
  const q = query({
    prompt: iterable,
    options: baseOptions(offer, {
      env: {},
      // A per-query turn bound would end the whole query after one assistant
      // message, so the bound has to cover every step of the conversation.
      options: { persistSession: false, maxTurns: STEPS * 4 },
    }),
  })
  push(renderWhole(messages))
  let step = 0
  let t0 = Date.now()
  let assistants = []
  try {
    for await (const message of q) {
      if (message.type === 'assistant') assistants.push(message)
      if (message.type === 'result') {
        const answer = answerOf(assistants)
        steps.push({
          step: step + 1,
          ms: Date.now() - t0,
          subtype: message.subtype,
          calls: answer.calls.length,
          ...usageOf(message),
        })
        assistants = []
        step += 1
        if (step >= STEPS || answer.calls.length === 0) break
        t0 = Date.now()
        push(renderDelta({ toolResultFor: answer.calls[0]?.id ?? 'none', text: cannedResult(step - 1) }))
      }
    }
  } catch (error) {
    steps.push({ step: step + 1, ms: Date.now() - t0, subtype: `THROW ${String(error).slice(0, 200)}`, calls: 0, input: 0, output: 0, cacheWrite: 0, cacheRead: 0 })
  }
  closed = true
  enqueue(undefined)
  try {
    q.close?.()
  } catch {
    // Closing an already-finished query is a no-op that may throw.
  }
  await offer.close()
}

function report(steps, wallMs, processStarts) {
  const total = steps.reduce((acc, s) => ({
    output: acc.output + s.output,
    cacheWrite: acc.cacheWrite + s.cacheWrite,
    cacheRead: acc.cacheRead + s.cacheRead,
    input: acc.input + s.input,
  }), { output: 0, cacheWrite: 0, cacheRead: 0, input: 0 })
  console.log(JSON.stringify({
    design: DESIGN,
    steps: steps.length,
    processStarts,
    wallMs,
    totals: total,
    diskBytes: DESIGN === 'B' ? diskBytes(CONFIG_DIR) : 0,
    perStep: steps,
  }, null, 2))
}

await main()

