/** Control: does a resumed session read the prefix it already holds from cache? */
import { mkdirSync, rmSync } from 'node:fs'
import { randomUUID } from 'node:crypto'
import { query } from '@anthropic-ai/claude-agent-sdk'

const EXECUTABLE = process.env.PROBE_CLAUDE ?? '/opt/node22/bin/claude'
const CONFIG_DIR = '/tmp/route-probe/resume-config'
const SCOPED = process.env.PROBE_SCOPE_CONFIG === '1'
rmSync(CONFIG_DIR, { recursive: true, force: true })
mkdirSync(CONFIG_DIR, { recursive: true })

const filler = Array.from({ length: 400 }, (_, i) =>
  `export const value${i} = { index: ${i}, label: 'usage-field-${i}', disjoint: ${i % 2 === 0} }`).join('\n')
const SYSTEM = 'You are the implementer agent of an automated software harness. Answer one turn at a time.'

async function run(label, prompt, extra) {
  const t0 = Date.now()
  const q = query({
    prompt,
    options: {
      cwd: '/tmp/route-probe',
      pathToClaudeCodeExecutable: EXECUTABLE,
      env: { ...process.env, ...SCOPED ? { CLAUDE_CONFIG_DIR: CONFIG_DIR } : {} },
      systemPrompt: SYSTEM,
      maxTurns: 1,
      permissionMode: 'dontAsk',
      tools: [],
      allowedTools: [],
      settingSources: [],
      persistSession: true,
      ...extra,
    },
  })
  let result
  try {
    for await (const m of q) if (m.type === 'result') result = m
  } catch (error) {
    if (result === undefined) throw error
  }
  const u = result?.usage ?? {}
  console.log(label, JSON.stringify({
    ms: Date.now() - t0,
    session: result?.session_id,
    subtype: result?.subtype,
    input: u.input_tokens,
    output: u.output_tokens,
    cacheWrite: u.cache_creation_input_tokens,
    cacheRead: u.cache_read_input_tokens,
  }))
  return result?.session_id
}

const id = randomUUID()
const session = await run('turn1 ', `Read the module below and answer in one sentence whether it computes token usage.\n\n${filler}\n`, { sessionId: id })
await run('turn2 ', 'Now answer in one sentence whether its counts are disjoint.', { resume: session })
await run('turn3 ', 'Now answer in one sentence which field carries cache reads.', { resume: session })

