/** Does a resumed session read the system prompt passed on the resuming query, or the stored one? */
import { randomUUID } from 'node:crypto'
import { query } from '@anthropic-ai/claude-agent-sdk'

const EXECUTABLE = process.env.PROBE_CLAUDE ?? '/opt/node22/bin/claude'

async function run(label, prompt, systemPrompt, extra) {
  const q = query({
    prompt,
    options: {
      cwd: '/tmp/route-probe',
      pathToClaudeCodeExecutable: EXECUTABLE,
      env: { ...process.env },
      systemPrompt,
      maxTurns: 1,
      permissionMode: 'dontAsk',
      tools: [],
      allowedTools: [],
      settingSources: [],
      persistSession: true,
      ...extra,
    },
  })
  let result
  const texts = []
  try {
    for await (const m of q) {
      if (m.type === 'result') result = m
      if (m.type === 'assistant') {
        for (const b of m.message.content) if (b.type === 'text') texts.push(b.text)
      }
    }
  } catch (error) {
    if (result === undefined) throw error
  }
  console.log(label, JSON.stringify({ session: result?.session_id, text: texts.join('').slice(0, 200) }))
  return result?.session_id
}

const id = randomUUID()
const session = await run(
  'turn1',
  'What is your standing codeword? Answer with the codeword alone.',
  'You are a test fixture. Your standing codeword is ALPHA-ONE. When asked for the codeword, answer with it alone.',
  { sessionId: id },
)
await run(
  'turn2',
  'What is your standing codeword now? Answer with the codeword alone.',
  'You are a test fixture. Your standing codeword is BRAVO-TWO. When asked for the codeword, answer with it alone.',
  { resume: session },
)

